import React, { useMemo, useState } from 'react';
import { Table, TableHead, TableBody, TableRow, TableCell, Badge, Pagination } from '@jinx-ui/react';

interface User {
  id: string | number;
  name: string;
  role: string;
  status: 'active' | 'disabled';
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const UsersTable: React.FC<UsersTableProps> = ({ users }) => {
  const [page, setPage] = useState(1);

  const totalPages = Math.max(1, Math.ceil(users.length / PAGE_SIZE));

  const currentUsers = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, page]);

  return (
    <div className="jx-stack jx-gap-md">
      <Table className="jx-table">
        <TableHead>
          <TableRow>
            <TableCell as="th">Имя</TableCell>
            <TableCell as="th">Роль</TableCell>
            <TableCell as="th">Статус</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {currentUsers.map((user) => (
            <TableRow key={user.id}>
              <TableCell>{user.name}</TableCell>
              <TableCell>{user.role}</TableCell>
              <TableCell>
                <Badge tone={user.status === 'active' ? 'success' : 'neutral'}>
                  {user.status === 'active' ? 'Активен' : 'Отключён'}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
      <Pagination
        className="jx-flex jx-justify-center"
        page={page}
        totalPages={totalPages}
        onPageChange={setPage}
      />
    </div>
  );
};

export default UsersTable;

